package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAnuradhapuraMuralBank1 {
    private const val T = "අනුරාධපුර යුගයේ බිතුසිතුවම් කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ අනුරාධපුර යුගයට අයත් ලෝක ප්‍රකට සීගිරි බිතුසිතුවම් නිර්මාණය වූයේ කුමන සියවසේදීද?", "ක්‍රි.ව. 5 වන සියවසේදී", "ක්‍රි.ව. 12 වන සියවසේදී", "ක්‍රි.ව. 18 වන සියවසේදී", "ක්‍රි.පූ. 3 වන සියවසේදී", "ක්‍රි.ව. 477–495 අතර කාලයේ කාශ්‍යප රජතුමාගේ අනුග්‍රහයෙන් සීගිරි සිතුවම් නිර්මාණය විය."),
        q("සීගිරි රාජධානිය ගොඩනඟා බිතුසිතුවම් නිර්මාණය කිරීමට මූලික වූ රජතුමා කවුද?", "පළමුවන කාශ්‍යප රජතුමා", "මහා පරාක්‍රමබාහු රජතුමා", "කීර්ති ශ්‍රී රාජසිංහ රජතුමා", "දේවානම්පියතිස්ස රජතුමා", "ධාතුසේන රජුගේ පුත් කාශ්‍යප රජතුමා සීගිරි පර්වතය මුදුනේ රාජධානිය පිහිටුවා සිතුවම් කරවීය."),
        q("සීගිරි බිතුසිතුවම්වලින් බහුතරයක් අදටත් දක්නට ලැබෙන්නේ පර්වතයේ කුමන ස්ථානයේද?", "බටහිර මුහුණතේ පිහිටි ලෙන් කුටීරයේ", "පර්වතය මුදුනේ රජ මාලිගයේ", "නැගෙනහිර කොටු පවුරේ", "දිය අගලේ ගල් බැම්ම මත", "සීගිරි ගලේ බටහිර මුහුණතේ ඉහළින් පිහිටි ලෙන් පොකුණේ මෙම සිතුවම් ඇත."),
        q("සීගිරි සිතුවම් ඇඳීමේදී භාවිත කර ඇති බදාම තාක්ෂණික ක්‍රමවේදය කුමක්ද?", "ෆ්‍රෙස්කෝ සෙක්කෝ හෙවත් වියළි බදාම ක්‍රමය", "තෙල් සායම් කැන්වස් ක්‍රමය", "මොසැයික් පිඟන් කැටයම් ක්‍රමය", "එන්කෝස්ටික් උණු ඉටි ක්‍රමය", "වියළුණු බදාමය මත ද්‍රව බන්ධකයක් සමඟ වර්ණ ආලේප කිරීමේ ෆ්‍රෙස්කෝ සෙක්කෝ ක්‍රමය යොදාගෙන ඇත."),
        q("සීගිරි බිතුසිතුවම් සඳහා සකස් කළ මූලික බදාම තට්ටුවේ ප්‍රධාන සංඝටක මොනවාද?", "රතු මැටි, දහයියා, කෙඳි සහ හුණු", "සිමෙන්ති, කළුගල් කුඩු සහ තාර", "ප්ලාස්ටර් ඔෆ් පැරිස් සහ රසදිය", "රබර් කිරි, සීනි සහ පාන් පිටි", "රළු රතු මැටි හා දහයියා මිශ්‍ර පළමු තට්ටුව මත සිනිඳු මැටි හා සුදු හුණු තට්ටුව යොදා ඇත."),
        q("සීගිරි සිතුවම්වල කිසිසේත් භාවිත කර නොමැති ප්‍රධාන වර්ණය කුමක්ද?", "නිල් වර්ණය", "රතු වර්ණය", "කහ වර්ණය", "කොළ වර්ණය", "සීගිරි සිතුවම්වල රතු, කහ, කොළ, කළු හා සුදු වර්ණ යොදා ඇති මුත් නිල් වර්ණය දක්නට නැත."),
        q("සීගිරි බිතුසිතුවම්වල නිරූපණය කර ඇති කාන්තා රූප හැඳින්වෙන්නේ කෙසේද?", "සීගිරි අප්සරාවන් හෙවත් මේඝලතා හා විජ්ජුලතා", "මහනුවර පත්තිනි දේවතාවියන්", "පොළොන්නරුවේ ගෝපිකාවන්", "සීතාවක කුමාරිකාවන්", "සෙනරත් පරණවිතානයන් මෙම රූප වලාකුළු හා විදුලි කුමරියන් ලෙස අර්ථකථනය කර ඇත."),
        q("සීගිරි සිතුවම්වල කාන්තා රූපවල ඉඟටියෙන් පහළ කොටස නොපෙනී තිබෙන්නේ කුමක් සංකේතවත් කරමින්ද?", "වලාකුළුවලින් වැසී අහසේ ගමන් කරන බව", "සිතුවම් අසම්පූර්ණව නතර කළ බව", "පහළ කොටස් වර්ෂාවට සේදී ගිය බව", "රාජ ආඥාවකින් පහළ කොටස් මකා දැමූ බව", "වලාකුළු හැඩැති තීරු ඉඟටිය වටා යොදා ඔවුන් ආකාශගාමී දෙවඟනන් ලෙස දක්වා ඇත."),
        q("මහාචාර්ය සෙනරත් පරණවිතානයන්ගේ මතය අනුව සීගිරි සිතුවම්වල රන්වන් පැහැ කාන්තාවන් කවුරුන් නියෝජනය කරයිද?", "විජ්ජුලතා හෙවත් විදුලි කුමරියන්", "රජ මාලිගාවේ සේවිකාවන්", "දඹදෙණි නගරයේ නළඟනන්", "සීගිරි කඳු පාමුල ගොවි කතුන්", "රන්වන් රූප විජ්ජුලතාවන් ලෙසත් අඳුරු රූප මේඝලතාවන් ලෙසත් ඔහු හඳුන්වයි."),
        q("මහාචාර්ය නන්දදේව විජේසේකර ඇතුළු ඇතැම් විද්වතුන්ගේ මතය අනුව සීගිරි කාන්තාවන් සිදු කරන්නේ කුමක්ද?", "පිදුරංගල විහාරයට මල් පූජාවට යාම", "රාජ සභාවේ වන්නම් නැටීම", "කැලණි විහාරය වන්දනා කිරීම", "සීගිරි වැවේ දිය කෙළියේ යෙදීම", "අත්වල මල් තැටි හා පූජා භාණ්ඩ දරා සිටීම නිසා පූජාවකට යන බව එම මතයෙන් කියැවේ."),
        q("හෙන්රි බෙල් මහතාගේ මතය අනුව සීගිරි බිතුසිතුවම්වල දැක්වෙන්නේ කවුරුන්ද?", "පිදුරංගල විහාරය වැඳීමට යන කාශ්‍යප රජුගේ අන්තඃපුර ස්ත්‍රීන්", "මහා පරාක්‍රමබාහු රජුගේ සේනාධිනායකයන්", "දුටුගැමුණු රජුගේ දස මහ යෝධයන්", "කුවේණියගේ යක්ෂ ගෝත්‍රික පිරිවර", "බෙල් මහතා මුල් කාලයේ මෙම රූප රජුගේ අන්තඃපුර කාන්තාවන් හා පරිවාර ස්ත්‍රීන් ලෙස හඳුන්වනු ලැබීය."),
        q("සීගිරි සිතුවම්වල අඳුරු පැහැති කාන්තා රූප මහාචාර්ය පරණවිතානයන් විසින් හඳුන්වනු ලැබුවේ කුමන නමින්ද?", "මේඝලතා හෙවත් වැහි වලාකුළු කුමරියන්", "සඳකිඳුරියන් හා වන දෙවඟනන්", "මහමායා දේවිය හා පජාපතී ගෝතමිය", "රතී සහ පත්තිනි දේවතාවියන්", "අඳුරු කොළ-මිශ්‍ර සමක් ඇති කාන්තාවන් වලාකුළු නියෝජනය කරන මේඝලතාවන් ලෙස ඔහු අර්ථ දැක්වීය."),
        q("සීගිරි සිතුවම්වල කාන්තාවන් අත ඇති මල් මගින් පූජනීය ගෞරවයට අමතරව දැක්වෙන අදහස කුමක්ද?", "සොබාදහමේ සශ්‍රීකත්වය හා රාජකීය සුන්දරත්වය", "මල් වෙළඳපොළේ මිල ප්‍රදර්ශනය කිරීම", "වෛද්‍ය ශාස්ත්‍රයේ ඖෂධ හඳුන්වා දීම", "මල් උයන් සැලසුම් සිතියම දැක්වීම", "මානෙල්, නෙළුම් හා අරලිය වැනි මල් පූජනීය භක්තිය හා සශ්‍රීකත්වය සංකේතවත් කරයි."),
        q("සීගිරි බිතුසිතුවම්වල 'ත්‍රිමාණ බව' මතු කිරීමට කලාකරුවා යොදා ගත් ප්‍රධාන උපක්‍රමය කුමක්ද?", "වර්ණ ශ්‍රේණිගත කිරීම හෙවත් ආලෝක-අඳුරු සෙවණැලි යෙදීම", "සිරුර වටා ඝන රන් තහඩු ඔබ්බවා තැබීම", "පසුබිම කළු තීන්තවලින් සම්පූර්ණයෙන් වැසීම", "රූප සියල්ල චතුරස්‍ර කොටු තුළ ඇඳීම", "වර්ණ මිශ්‍ර කර ශරීර අවයවවල වටකුරු බව මතු කිරීම සීගිරි චිත්‍රවල විශිෂ්ට ලක්ෂණයකි."),
        q("සීගිරි චිත්‍ර ශිල්පියාගේ නිදහස් රේඛා කුසලතාව වඩාත් හොඳින් පෙනෙන සාධකය කුමක්ද?", "අතක් ඇඳීමේදී වැරදුණු මුල් රේඛාව මත නිවැරදි රේඛාව ඇඳීම", "සෑම රූපයක්ම කෝදුවක් තබා කෙළින් ඇඳීම", "කවකටුවෙන් සියලු මුහුණු වෘත්තාකාරව ඇඳීම", "පසුබිමේ කඳු හා ගංගා රේඛා ඇඳීම", "සීගිරි ලලනාවකගේ අතක වෙනස් කළ මුල් රේඛා සටහනින් ශිල්පියාගේ නිදහස් හස්ත කුසලතාව හෙළි වේ."),
        q("සීගිරි සිතුවම්වල කාන්තා රූපවල ඉදිරිපත් කර ඇති මුහුණු පිහිටීමේ විලාසය කුමක්ද?", "තුන්කාල (Three-quarter) හා අර්ධ පැතිකඩ විලාසය", "සම්පූර්ණ පිටුපස හැරුණු විලාසය", "සෘජු ඉදිරිපස මුහුණු විලාසය පමණි", "උඩු යටිකුරු මුහුණු විලාසය", "බොහෝ සීගිරි ලලනාවන්ගේ මුහුණු තුන්කාල ඉරියව්වෙන් නිරූපණය කර සිරුරේ හැඩය මතු කර ඇත."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති කාන්තාවන්ගේ දෑස් හා දෙබැම දක්වා ඇති ආකාරය කෙබඳුද?", "දිගටි මානෙල් පෙති වැනි ඇස් සහ දුන්නක් වැනි දෙබැම", "වටකුරු පිඟන් වැනි විශාල ඇස්", "කෙළින් ඉරි කැබලි වැනි කුඩා ඇස්", "සම්පූර්ණයෙන් වසාගත් ඇස් පියන්", "පෙරදිග සම්භාව්‍ය කාව්‍ය ලක්ෂණවලට අනුව දිගටි නෙත් හා දුනු බැම ඇඳ තිබේ."),
        q("සීගිරි ලලනාවන්ගේ හිස් පළඳනා සහ ආභරණ අධ්‍යයනය කිරීමෙන් හඳුනාගත හැකි කරුණ කුමක්ද?", "ක්‍රි.ව. 5 වන සියවසේ උසස් රාජකීය විලාසිතා හා ශිල්පීය දැනුම", "පෘතුගීසි යටත්විජිත සමයේ ආභරණ ක්‍රම", "නූතන ප්ලාස්ටික් විලාසිතා සැලසුම්", "යුරෝපීය මධ්‍යකාලීන යුද ඇඳුම්", "ඔටුණු, මාල, වළලු, කුණ්ඩලාභරණ හා කේශ කලාප රටා එවකට පැවති සංස්කෘතික සමෘද්ධිය පෙන්වයි."),
        q("සීගිරියේ පිහිටි කැටපත් පවුර මත ලියැවී ඇති සීගිරි කුරුටු ගී සිතුවම් හා සම්බන්ධ වන්නේ කෙසේද?", "සිතුවම් දැක ආස්වාදය ලැබූ නරඹන්නන්ගේ කාව්‍යමය ප්‍රතිචාර ලෙස", "සිතුවම් ඇඳීමට ගිය වියදම් බිල්පත් ලෙස", "රජුගේ හමුදා නියෝග ලැයිස්තුව ලෙස", "චිත්‍ර ශිල්පීන්ගේ බදු නාම ලේඛනය ලෙස", "ක්‍රි.ව. 6 සිට 14 දක්වා කාලයේ සීගිරි සිතුවම් නැරඹූ රසිකයෝ කැටපත් පවුරේ කවි කෙටූහ."),
        q("සීගිරි කුරුටු ගී අනුව අතීතයේ සීගිරියේ කාන්තා සිතුවම් කොපමණ සංඛ්‍යාවක් පමණ තිබූ බව සඳහන් වේද?", "රන්වන් ලලනාවන් පන්සියයක්", "රන්වන් ලලනාවන් දහයක්", "රන්වන් ලලනාවන් දසදහසක්", "රන්වන් ලලනාවන් දෙකක්", "'පන්සියක් අගනන්' ආදී කුරුටු ගී උපුටන අනුව අතීතයේ සිතුවම් රැසක් තිබී ඇති අතර අද 22ක් පමණ ඉතිරිය."),
        q("සීගිරි බිතුසිතුවම්වල රතු වර්ණය සාදා ගැනීමට භාවිත කළ ස්වභාවික ඛනිජය කුමක්ද?", "සාදිලිංගම් හෝ රතු ගුරුගල්", "කොපර් සල්ෆේට් නිල් කුඩු", "ලැපිස් ලාසුලි ඛනිජය", "ගම්බෝජ් හෙවත් ගොකටු කිරි", "දේශීයව ලබා ගත් රතු ගුරුගල් සීගිරි චිත්‍රවල ප්‍රධාන රතු වර්ණකය විය."),
        q("සීගිරි සිතුවම්වල භාවිත කර ඇති කහ වර්ණකය ලබා ගත් ස්වභාවික මූලාශ්‍රය කුමක්ද?", "කහ ගුරුගල් හෙවත් ලිමොනයිට්", "කහ පැහැති ඉටිපන්දම්", "නූතන කැඩ්මියම් කහ කුඩු", "තඹ පාසි දියර", "ස්වභාවික කහ ගුරුගල් හා හිරියල් වැනි ඛනිජ වර්ණක අඹරා කහ පැහැය ලබා ගෙන ඇත."),
        q("සීගිරි සිතුවම්වල කොළ වර්ණය නිපදවා ඇත්තේ කුමන ඛනිජ වර්ගයකින්ද?", "ග්ලෝකෝනයිට් හෙවත් ටෙරා වර්ට් නම් කොළ පස්", "කෘත්‍රිම ප්ලාස්ටික් ඩයි", "නිල් මැණික් සහ අඟුරු", "සාදිලිංගම් සහ හුණු", "ස්වභාවික කොළ පැහැති මැටි හෙවත් ටෙරා වර්ට් සීගිරි චිත්‍රවල කොළ පැහැයට යොදා ගැනිණි."),
        q("සීගිරි සිතුවම්වල සුදු වර්ණය සඳහාත් බදාම ඔප දැමීම සඳහාත් යොදා ගත් ප්‍රධාන ද්‍රව්‍යය කුමක්ද?", "දහයියා රහිත සිනිඳු හුණු සහ මකුළු මැටි", "සිමෙන්ති කුඩු සහ වැලි", "චීන පිඟන් මැටි ඔප කුඩු", "සුදු තෙල් සායම්", "පිළිස්සූ හුණු හා මකුළු මැටි සීගිරි බදාමයේ ඉහළ ස්තරය හා සුදු වර්ණය සඳහා යොදාගෙන ඇත."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති කාන්තා රූපවල උඩුකය ආවරණ ඇති හා නැති ලක්ෂණයෙන් පෙනෙන්නේ කුමක්ද?", "රාජකීය හා දිව්‍යමය සංකේතවත් භේදය හෝ ඇඳුම් විලාසිතාව", "සිතුවම් ශිල්පීන්ට ඇඳුම් ඇඳීමට අමතක වීම", "තීන්ත මදි වීමෙන් සමහර ඇඳුම් අත්හැරීම", "විනාශකාරීන් විසින් ඇඳුම් සූරා දැමීම", "රන්වන් ලලනාවන් බොහෝ විට නිරාවරණ උඩුකයකින්ද අඳුරු ලලනාවන් තනපට පැළඳද සිටීම විශේෂයකි."),
        q("1967 වසරේදී සීගිරි බිතුසිතුවම්වලට හානි සිදු වූ විට ඒවා විද්‍යාත්මකව ප්‍රතිසංස්කරණය කිරීමට පැමිණි ඉතාලි විශේෂඥයා කවුද?", "ලුසියානෝ මරන්සි මහතා", "ලියොනාඩෝ ඩා වින්චි මහතා", "මයිකල්ඇන්ජලෝ මහතා", "හෙන්රි මැටිස් මහතා", "1967 දී කළු තීන්ත ගා චිත්‍රවලට හානි කළ පසු ඉතාලි ජාතික ලුසියානෝ මරන්සි මහතා එය යථා තත්ත්වයට පත් කළේය."),
        q("සීගිරි බිතුසිතුවම් ප්‍රථම වරට වර්ණවත් අනුරූ ලෙස පිටපත් කළ බ්‍රිතාන්‍ය ශිල්පියා කවුද?", "ඒ. මරේ (A. Murray) මහතා", "රූබන්ස් මහතා", "කොන්ස්ටබල් මහතා", "ටර්නර් මහතා", "1889 දී බ්‍රිතාන්‍ය ජාතික ඒ. මරේ මහතා සීගිරි සිතුවම් පැස්ටල් මගින් පිටපත් කර කොළඹ කෞතුකාගාරයට ලබා දුන්නේය."),
        q("සීගිරි ලෙන් සිතුවම් සංගමනය හෙවත් ඒකාබද්ධතාවය පවත්වා ඇති ආකාරය කෙබඳුද?", "රූප යුගල හෝ තනි රූප අතර මනා රිද්මයානුකූල බැඳීමකින්", "සෑම රූපයක්ම වෙන් වෙන් කළු කොටු තුළ රඳවා", "රූප එකිනෙකට පිටුපා ඉවත බලා සිටින සේ", "පසුබිම කළු රේඛා දැලකින් ආවරණය කර", "රූප දෙක බැගින් සමීපව ගෙන හිස් හැරවීම හා අත් චලනය මගින් එකිනෙකා අතර සංවාදයක් මවා ඇත."),
        q("සීගිරි සිතුවම් සීගිරි ශෛලිය ලෙස සුවිශේෂී වීමට ඉන්දියාවේ කුමන චිත්‍ර සම්ප්‍රදායේ ආභාසය සමඟ සසඳනු ලැබේද?", "අජන්තා බිතුසිතුවම් සම්ප්‍රදාය", "මූගල් කුඩා චිත්‍ර සම්ප්‍රදාය", "රාජ්පුත් ජල සායම් සම්ප්‍රදාය", "මධුබනී ජන චිත්‍ර සම්ප්‍රදාය", "ක්‍රි.ව. 5 වන සියවසේ අජන්තා චිත්‍ර හා සීගිරි චිත්‍ර අතර සමානකම් මෙන්ම සීගිරියට ආවේණික ලක්ෂණද ඇත."),
        q("අජන්තා සිතුවම් හා සැසඳීමේදී සීගිරි සිතුවම්වල දක්නට ලැබෙන සුවිශේෂී දේශීය වෙනස්කම කුමක්ද?", "වඩාත් නිදහස් ජවසම්පන්න රේඛාව හා දිව්‍යමය උඩුකය රූප පමණක් වීම", "තෙල් සායම් කැන්වස් භාවිතය", "ජාතක කතා සියල්ලම සිරස් තීරුවල ඇඳීම", "නිල් වර්ණයෙන් පමණක් පසුබිම වැසීම", "අජන්තාවේ බෞද්ධ ආඛ්‍යාන සම්පූර්ණ රූප තිබුණද සීගිරියේ ඉඟටියෙන් ඉහළ දිව්‍ය ලලනාවන් වේ."),
        q("සීගිරි ගුහාවල ඇඳ ඇති කාන්තා රූප යුගල වශයෙන් නිරූපණය වන විට ඒවායේ චරිත දෙක වෙනස් වන්නේ කෙසේද?", "වංශවත් කුමාරිකාවක් සහ ඇගේ සේවිකාව හෝ මේඝලතා-විජ්ජුලතා ලෙස", "රජතුමා සහ සතුරු සෙන්පතියා ලෙස", "ළදරුවෙකු සහ වයෝවෘද්ධ පුරුෂයෙකු ලෙස", "සිංහයෙකු සහ කාන්තාවක ලෙස", "රන්වන් කාන්තාව සමඟ අඳුරු පැහැති තනපට පැළඳි කාන්තාව යුගල ලෙස යෙදී ඇත."),
        q("සීගිරි පර්වතයේ ලෙන් කුටීරයෙන් පිටත උද්‍යාන ගල්වල පවා සිතුවම් තිබූ බව සනාථ වන්නේ කෙසේද?", "නයිපෙණ ගුහාව හා අනෙකුත් ගල් පියසිවල ඇති සිතුවම් ශේෂවලින්", "මහාවංශයේ තෙල් සායම් ගබඩා ගැන ලියා තිබීමෙන්", "ගල් මුදුනේ රන් පුවරු හමුවීමෙන්", "දිය අගලේ ලෝකඩ චිත්‍ර හමුවීමෙන්", "නයිපෙණ ගුහාව හෙවත් ඩෙරණියගල ගුහාවේ පැරණි බදාම හා ජ්‍යාමිතික රූප ශේෂ අදටත් දක්නට ඇත."),
        q("සීගිරියේ ඇති නයිපෙණ ගුහාවේ (Cobra Hood Cave) දක්නට ලැබෙන පැරණි සිතුවම් ලක්ෂණය කුමක්ද?", "රතු හා කහ රේඛා, ලියවැල් හා මල් මෝස්තර ශේෂ", "චීන ද්‍රව්‍ය කැටයම්", "පෘතුගීසි රජවරුන්ගේ ආලේඛ්‍ය චිත්‍ර", "කළුගල් වලින් කළ චිත්‍ර පෙළ", "පර්වත මූලයන්හි ශිලා උද්‍යාන ලෙන්වල පවා රතු හා කහ රටා බදාම මත ඇඳ තිබී ඇත."),
        q("සීගිරි බිතුසිතුවම්වල කාන්තාවන්ගේ අත්වල මුද්‍රා හා ඉරියව් මගින් චිත්‍රයට එක් කර ඇති ගුණාංගය කුමක්ද?", "සියුම් නම්‍යශීලී බව, රිද්මය හා චලනය", "දැඩි යුදමය ස්ථාවරත්වය", "භයංකර බව හා කෝපය", "නිශ්චල ජ්‍යාමිතික දැඩි බව", "මල් නෙළන හා විසිරුවන සියුම් ඇඟිලි ඉරියව් රූපවලට සජීවී සුන්දරත්වයක් ගෙන දෙයි."),
        q("සීගිරි සිතුවම් වෘත්තීයමය සැලසුමකින් යුතුව නිම කළ බවට ඇති සාක්ෂිය කුමක්ද?", "ගල් පර්වතය කෙටීමෙන් සකස් කර බදාම තට්ටු දෙකක් යෙදීම", "සිතුවම් මත ශිල්පීන්ගේ නම් අත්සන් කිරීම", "ප්ලාස්ටික් ශීට් මත ඇඳ ගලේ ඇලවීම", "විදුලි පහන් පද්ධති ගුහාවේ සවි කිරීම", "පර්වත මතුපිට පිහිටුවා බදාම ස්තර දෙකක් නිසි ලෙස සැකසීම දියුණු ශිල්පීය ක්‍රමයකි."),
        q("සීගිරියේ බිතුසිතුවම් නිර්මාණයේදී බදාමයට දහයියා සහ ශාක කෙඳි මිශ්‍ර කිරීමේ විද්‍යාත්මක අරමුණ කුමක්ද?", "බදාමය වියළීමේදී පිපිරීම වැළැක්වීම හා ශක්තිය වැඩි කිරීම", "බදාමයට සුවඳක් ලබා දීම", "මැටි පැහැය කොළ පැහැයට හැරවීම", "බදාමය ජලයේ දිය කර හැරීම", "දහයියා හා කෙඳි බදාමයේ ආතතිය පාලනය කර ඉරි තැළීමකින් තොරව සියවස් ගණනක් පවත්වා ගනී."),
        q("සීගිරි ලලනාවන්ගේ ශරීර අනුපාත (Proportions) සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය කුමක්ද?", "සිහින් ඉඟටිය, පුළුල් උරහිස් හා සුන්දර ලාලිත්‍යමය හැඩය", "ඉතා කෙටි උසකින් යුත් සතරැස් සිරුරු", "ඉදිමුණු හා රළු මිනිස් සිරුරු", "ජ්‍යාමිතික ත්‍රිකෝණවලට සමාන හැඩය", "සම්භාව්‍ය පෙරදිග කාන්තා සෞන්දර්ය ලක්ෂණ අනුව සිහින් ඉඟ හා ලාලිත්‍යය දක්වා ඇත."),
        q("සීගිරි සිතුවම්වල ඇඳ ඇති සමහර කාන්තා රූපවල ඉණ ප්‍රදේශයේ පළඳවා ඇති මේඛලා දාමය යනු කුමක්ද?", "ඉණ වටා පළඳින රන් හෝ මැණික් ආභරණ පටිය", "හිස මත තබන මල් වට්ටිය", "අතේ දරන නෙළුම් මල", "කනේ පළඳින තෝඩු යුගලය", "මේඛලා දාමය යනු පැරණි කාන්තාවන් ඉණ අලංකාර කිරීමට පැළඳි ආභරණයකි."),
        q("සීගිරි සිතුවම් සියවස් පහළොවකට අධික කාලයක් තිස්සේ සුරැකී තිබීමට බලපෑ ස්වභාවික හේතුව කුමක්ද?", "පර්වතය ඇතුළට නෙරා පිහිටි ලෙන් කුහරය වැස්සෙන් හා හිරුගෙන් ආරක්ෂා වීම", "නිරන්තරයෙන් වැසි ජලයෙන් සිතුවම් සේදී යාම", "සිතුවම් මත ප්ලාස්ටික් ආවරණයක් තිබීම", "ගුහාව සම්පූර්ණයෙන් පස්වලින් වැසී තිබීම", "ස්වභාවික ගල් පියස්ස හිරු රශ්මිය හා මෝසම් වැසිවලින් සිතුවම් ආවරණය කරයි."),
        q("සීගිරි කුරුටු ගී රචකයන් අතරින් එක් කවියෙකු තමා රන්වන් හා නිල්වන් ලියන් දුටු බව පැවසීමෙන් තහවුරු වන්නේ කුමක්ද?", "මුල් යුගයේ සිටම මෙම වර්ණ වෙනස සිතුවම්වල පැවති බව", "කුරුටු ගී කවියන් වර්ණ අන්ධභාවයෙන් පෙළුණු බව", "චිත්‍රවල පසුබිම නිල් තීන්තවලින් වසා තිබූ බව", "සියලු චිත්‍ර එකම වර්ණයෙන් ඇඳ තිබූ බව", "රන්වන් හා අඳුරු පැහැ කාන්තා වෙනස ක්‍රි.ව. 8–9 සියවස්වල කවියන්ගේ ඇසටද පැහැදිලිව හසු විය."),
        q("සීගිරි බිතුසිතුවම්වල රූපවල බාහිර මායිම් දැක්වීමට චිත්‍ර ශිල්පියා යොදා ඇති ප්‍රධාන රේඛා වර්ණය කුමක්ද?", "තද රතු දුඹුරු හෝ කළු රේඛාව", "දීප්තිමත් රෝස පැහැති රේඛාව", "සුදු පැහැති හුණු රේඛාව පමණි", "රන්වන් තීන්ත රේඛාව", "රූපවල බාහිර සීමා සඳහා තද රතු දුඹුරු හා කළු පැහැති රිද්මයානුකූල රේඛා යොදාගෙන ඇත."),
        q("සීගිරි සිතුවම්වල සමූහගත ගුණය බිඳ නොවැටෙන ලෙස පසුබිම සකස් කර ඇත්තේ කෙසේද?", "වලාකුළු හැඩැති මෘදු පසුබිමක රූප පාවෙන සේ දැක්වීමෙන්", "පසුබිමේ විශාල රජ මාලිගා ඇඳීමෙන්", "කළු පැහැති චතුරස්‍ර කොටු ඇඳීමෙන්", "අකුරු පේළිවලින් පසුබිම පිරවීමෙන්", "පහළ කොටසේ ඇති වලාකුළු රටා රූප සියල්ල එකම ආකාශ අවකාශයක රඳවයි."),
        q("මහනුවර යුගයේ සිතුවම් හා සසඳන විට සීගිරි අනුරාධපුර සිතුවම්වල පැතලි බව වෙනුවට දක්නට ලැබෙන්නේ කුමක්ද?", "සියුම් වර්ණ සංකලනයෙන් මැවුණු ත්‍රිමාණ පරිමාව", "සම්පූර්ණ රේඛීය ජ්‍යාමිතික රටා පමණි", "තීරු ක්‍රමයට කතන්දර පෙළගැස්වීම", "පසුබිම තනි රතු පැහැයෙන් පමණක් පිරවීම", "මහනුවර පැතලි ශෛලිය මෙන් නොව සීගිරි චිත්‍ර පරිමාව සහිත සම්භාව්‍ය ශෛලියක් පෙන්වයි."),
        q("සීගිරි බිතුසිතුවම්වල මල් තැටියක් අතින් ගත් සේවිකාව හා මල් ඉසින කුමාරිකාව යන යුගලයෙන් පෙනෙන වෙනස කුමක්ද?", "අඳුරු හා ලා වර්ණ වෙනස හා ආභරණ ප්‍රමාණයේ වෙනස", "එක් අයෙකු ඉතා කුඩා කෘමියෙකු තරමට ඇඳීම", "දෙදෙනා දෙපසට හැරී සිටීම", "සේවිකාවගේ හිස නොඇඳ තැබීම", "ආභරණ, ඉරියව් සහ වර්ණ පැහැය මගින් ප්‍රධාන රූපය හා පරිවාර රූපය වෙන් කර දක්වයි."),
        q("සීගිරි ලෙන් සිතුවම්කරණයේදී බදාමය මත වර්ණ ගැන්වීමට පෙර කහ හෝ රතු පැහැයෙන් සිදු කළ මූලික පියවර කුමක්ද?", "දළ රූප සටහන ඇඳ ගැනීම", "බදාමය වතුරෙන් සෝදා හැරීම", "රන් පත්‍ර ඇලවීම", "පිඟන් කැබලි ඔබ්බවා තැබීම", "කහ හෝ රතු රේඛාවෙන් දළ සැකිල්ල ඇඳ පසුව වර්ණ ගන්වා අවසන් අඳුරු රේඛාව යොදා ඇත."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති මල් වර්ග අතර බහුලව හඳුනාගත හැකි දේශීය මල් මොනවාද?", "නෙළුම්, මානෙල් සහ සපු මල්", "රෝස, ටියුලිප් සහ සූරියකාන්ත", "ඕකිඩ්, ඩේසි සහ කානේෂන්", "චෙරි මල් සහ ලැවෙන්ඩර්", "දේශීය ජලජ මල් වන මානෙල්, නෙළුම් හා සුවඳ මල් සීගිරි ලලනාවන්ගේ දෑත්වල දක්නට ඇත."),
        q("සීගිරි සිතුවම් ලෝක උරුම කලා කෘති ලෙස අගය කිරීමට බලපාන ප්‍රධානතම හේතුව කුමක්ද?", "සම්භාව්‍ය ලාංකේය චිත්‍ර කලාවේ උච්චතම සෞන්දර්ය හා තාක්ෂණික විශිෂ්ටත්වය", "ලෝකයේ විශාලතම තෙල් සායම් කැන්වස් වීම", "පැරණි ග්‍රීක භාෂාවෙන් කවි ලියා තිබීම", "යුරෝපීය පුනරුද ශිල්පීන්ගේ නිර්මාණ වීම", "ක්‍රි.ව. 5 වන සියවස තරම් ඈත කාලයකදී මෙතරම් ජීවමාන චිත්‍ර බිහිවීම අද්විතීය වේ."),
        q("සීගිරි සිතුවම් ඇසුරෙන් හඳුනාගත හැකි අනුරාධපුර යුගයේ සංස්කෘතික අංගයක් වන්නේ කුමක්ද?", "කෙස් කළඹ සැරසීම, ආභරණ කර්මාන්තය හා රෙදිපිළි නිපුණතාව", "වීදුරු ජනෙල් කර්මාන්තය", "ලෝහ මුද්‍රණ කර්මාන්තය", "ප්ලාස්ටික් භාණ්ඩ නිෂ්පාදනය", "සියුම් මල් පටි, සිහින් සළු හා කැටයම් ආභරණ අනුරාධපුර යුගයේ ශිල්පීය සමෘද්ධිය පෙන්වයි."),
        q("සීගිරි කලාගාරයේ පර්වත ගුහා බිත්තිය වර්ණ ගැන්වීමට පෙර ගලෙහි කළ යුතු වූ මූලික කාර්යය කුමක්ද?", "ගලේ රළු කොටස් කොටා බදාමය රැඳෙන පරිදි සකස් කිරීම", "පර්වතය උණු කර සමතලා කිරීම", "වීදුරු පුවරු බිත්තියට ඇණ ගැසීම", "තෙල් ගා බිත්තිය ලිස්සන සුළු කිරීම", "බදාමය හොඳින් අල්ලා සිටීම සඳහා ගල් පෘෂ්ඨය රළු කටු ඉරි යොදා සූදානම් කර තිබේ."),
        q("සීගිරි සිතුවම්වල 'ලා' සහ 'තද' වර්ණ ශ්‍රේණිගත කිරීම (Chiaroscuro-like shading) සිදු කර ඇත්තේ කුමන ශෛලියකට අනුකූලවද?", "ශරීර අවයවවල වටකුරු බව මතු වන පරිදි රේඛා සමීපයේ තද කිරීමෙන්", "පැති බිත්තියේ විශාල කළු ඡායාවක් පොළොවට ඇඳීමෙන්", "මුළු චිත්‍රයම දුඹුරු පැහැයෙන් වැසීමෙන්", "සුදු තිත් මගින් අවකාශය පිරවීමෙන්", "රේඛා මායිම් ආසන්නයේ තද වර්ණ යොදා මැදට ලා කිරීමෙන් පිරුණු ත්‍රිමාණ බවක් ලැබී ඇත."),
        q("සීගිරි බිතුසිතුවම්වල කාන්තා රූපවල ඇඳ ඇති 'සළු හෙවත් දෝති' වල විශේෂ ලක්ෂණය කුමක්ද?", "විනිවිද පෙනෙන සිහින් ඉරි සහිත රෙදි ලෙස දැක්වීම", "ඝන සම්වලින් තැනූ කබා ලෙස දැක්වීම", "කළු පැහැති ලෝහ සන්නාහ ලෙස දැක්වීම", "පිදුරුවලින් ගෙතූ ඇඳුම් ලෙස දැක්වීම", "ඉරි සහිත සිහින් දුහුල් සළු ඇඳ තිබීම එකල පැවති උසස් පේෂකර්ම දියුණුව පෙන්වයි."),
        q("සීගිරි සිතුවම් ලෙන 'සිංහ පර්වතයේ' පිහිටි ආරක්ෂිත කලාගාරය ලෙස තෝරා ගැනීමට හේතුව කුමක්ද?", "ඉහළින් නෙරා ආ ගල් පියස්ස නිසා චිත්‍ර සුරැකෙන ස්වභාවික කුටීරයක් වීම", "එය පොළොව යට පිහිටි උමඟක් වීම", "සතුරන්ට පහසුවෙන් ළඟා විය හැකි පහළ බිමක් වීම", "එහි ජල උල්පතක් නිරන්තරයෙන් ගලා යාම", "ගල ඇතුළට හෑරී පවතින බටහිර මුහුණතේ කුහරය ස්වභාවිකවම හොඳින් ආරක්ෂා වී ඇත."),
        q("සීගිරි අප්සරාවන්ගේ අත්වල පළඳවා ඇති වළලු සහ බාහු වළලු (කේයූර) වලින් පෙනෙන ලක්ෂණය කුමක්ද?", "රාජකීය හා දිව්‍යමය උසස් තත්ත්වය", "දුගී ගැමි ජීවිතයේ සරල බව", "යුද භටයින්ගේ යකඩ පළිහ", "තාපස ජීවිතයේ අල්පේච්ඡ බව", "වැලමිටෙන් ඉහළ බාහු වළලු හා මැණික් කටුවේ වළලු ඉහළ සමාජ තත්ත්වය නිරූපණය කරයි."),
        q("සීගිරි බිතුසිතුවම් අධ්‍යයනයේදී 'බෙල්' මහතාට පසුව බොහෝ විචාරකයන් එම රූප ආගමික හෝ දිව්‍ය සංකල්ප ලෙස සැලකීමට හේතුව කුමක්ද?", "වලාකුළු පසුබිම සහ අහසේ ගමන් කරන ආකාරය", "බුදුන් වහන්සේගේ රුව මැදින් ඇඳ තිබීම", "ජාතක කතා නම් ලියා තිබීම", "පන්සල් ඝණ්ටාර ඇඳ තිබීම", "පාද හා දණහිස් වලාකුළුවලින් වැසී තිබීම මෙම රූප මනුෂ්‍ය ස්ත්‍රීන්ට වඩා දිව්‍යමය බව පෙන්වයි."),
        q("සීගිරි සිතුවම්වල භාවිත කළ බදාමය හා පසුකාලීන මහනුවර බදාමය අතර ප්‍රධාන වෙනස කුමක්ද?", "සීගිරි බදාමයේ දහයියා හා රතු මැටි ස්තරය ඉතා ශක්තිමත් ලෙස හුණු හා මුසු වීම", "සීගිරියේ බදාමය කඩදාසිවලින් සෑදීම", "මහනුවර බදාමයේ සිමෙන්ති පමණක් යෙදීම", "සීගිරියේ බදාම නොමැතිව ගලේම ඇඳීම", "සීගිරි බදාම තට්ටු ත්‍රිත්වය අධික කල්පැවැත්මකින් හා ජල ප්‍රතිරෝධී ගුණයකින් යුක්ත විය."),
        q("සීගිරි සිතුවම්වල 'සංස්කෘතික බන්ධකය' (Binder) ලෙස වර්ණ මැටි පෘෂ්ඨයට ඇලවීමට භාවිත කළ හැකි ද්‍රව්‍ය මොනවාද?", "ශාක මැලියම් හෝ දිවුල් ලාටු වැනි ස්වභාවික දියර", "කෘත්‍රිම පෙට්‍රෝලියම් තෙල්", "විනාකිරි සහ ලුණු දියර", "රසායනික සුපර් ග්ලූ", "දිවුල් ලාටු හෝ දොරණ තෙල් වැනි ස්වභාවික ශාක මැලියම් වර්ණ ස්ථිර කිරීමට යොදාගෙන ඇත."),
        q("සීගිරි කලාගාරයේ සිතුවම් අතර 'ප්‍රකට අප්සරාවන් දෙදෙනෙකු' එක ළඟ සිටින රූප යුගලයේ වර්ණ වෙනස කුමක්ද?", "රන්වන් කහ හා නිල්-කොළ අඳුරු පැහැය", "තනි සුදු සහ ලා දම් පැහැය", "තද නිල් හා රෝස පැහැය", "සම්පූර්ණ කළු සිලුවට් පැහැය", "අඳුරු කොළ පැහැති සමක් ඇති සේවිකාව හා රන්වන් සමක් ඇති කුමරිය සුප්‍රකට යුගලයකි."),
        q("සීගිරි ලලනාවන්ගේ 'නාසය හා තොල්' ඇඳ තිබෙන ආකාරයෙන් පෙන්නුම් කරන රේඛා ශිල්පය කුමක්ද?", "අඛණ්ඩ හා ස්ථිර සියුම් පින්සල් පහරවල්", "කැඩුණු හා රළු අඟුරු ඉරි", "ජ්‍යාමිතික කෙළින් කෝදු ඉරි", "කටු කම්බි වැනි දළ රේඛා", "පළපුරුදු පින්සල් පහරවලින් තොල්වල මෘදු බව හා නාසයේ සෘජු බව දක්වා ඇත."),
        q("සීගිරි කුරුටු ගී තුළින් චිත්‍ර රසවින්දනය ගැන හෙළි වන වැදගත් කාරණය කුමක්ද?", "සාමාන්‍ය ජනතාව පවා කලාව රසවිඳීමට හා කවි ලිවීමට තරම් උගත් වූ බව", "චිත්‍ර නැරඹීම රජ පවුලට පමණක් සීමා වූ බව", "සීගිරි සිතුවම් සියවස් ගණනක් සැඟවී තිබූ බව", "කවි ලිවීම තහනම් කර තිබූ බව", "දිවයිනේ විවිධ ප්‍රදේශවලින් පැමිණි ජනතාව සීගිරි සිතුවම් දැක උසස් රසාස්වාදයක් ලැබූහ."),
        q("සීගිරිය පර්වත පාමුල ඇති ජල උද්‍යාන හා පර්වත බිත්ති අතර පවතින 'ඒකාබද්ධ සැලසුම' කුමක්ද?", "ස්වභාවික පරිසරය, වාස්තු විද්‍යාව හා චිත්‍ර කලාව මනාව සංයෝජනය වීම", "චිත්‍ර පමණක් ගලේ ඇඳ උද්‍යාන අත්හැර දැමීම", "උද්‍යාන සම්පූර්ණයෙන් කොන්ක්‍රීට් කිරීම", "පර්වතය කඩා සමතලා නගරයක් තැනීම", "කාශ්‍යප රජුගේ සීගිරිය ලොව පැරණිතම සැලසුම් කළ උද්‍යාන නගර හා බිතුසිතුවම් සංකීර්ණයකි."),
        q("සීගිරි සිතුවම්වල කාන්තාවන්ගේ 'අත්ල සහ ඇඟිලි' නිරූපණය කර ඇති ආකාරය කෙබඳුද?", "සියුම්, දිගටි හා නර්තන මුද්‍රාවක මෙන් මෘදු ඉරියව්වලින්", "මිට මොළවා ගත් කෝපාවිෂ්ට ඉරියව්වලින්", "අත් නොපෙනෙන ලෙස සඟවාගෙන", "සෘජු කෙළින් දඬු මෙන් රළු ලෙස", "මල් නෙළන ඇඟිලිවල නම්‍යශීලී රේඛා සීගිරි චිත්‍ර ශිල්පියාගේ විශිෂ්ට මානව රූප දැනුම පෙන්වයි."),
        q("සීගිරි සිතුවම් අධ්‍යයනයේදී 'නන්දන හා අලකමන්දාව' යන සංකල්පය හා සම්බන්ධ කරන්නේ කුමන විද්වතාද?", "මහාචාර්ය සෙනරත් පරණවිතාන මහතා", "ආචාර්ය ආනන්ද කුමාරස්වාමි මහතා", "එච්. සී. පී. බෙල් මහතා", "මාර්ටින් වික්‍රමසිංහ මහතා", "කාශ්‍යප රජු කුවේරයා මෙන් ආලකමන්දාව තනා දිව්‍ය අප්සරාවන් සිතුවම් කළ බව පරණවිතාන මතයයි."),
        q("සීගිරි සිතුවම්වල 'පිහිටි රූප අතර පවතින කුඩා මල් පෙති' විසිරී තිබීමෙන් කලා කෘතියට ලැබෙන ආලෝකය කුමක්ද?", "සජීවී චලනය හා ආකාශයේ පාවෙන හැඟීම", "වර්ණ නාස්ති වීම හා අපිළිවෙළ", "රූප අතර ගැටුම හා අඳුර", "ගලේ ඉරි තැළීම් වැසීම පමණක්", "අවකාශයේ වැටෙන මල් පෙති චිත්‍රයට චලනය හා ප්‍රසන්න භාවයක් එක් කරයි."),
        q("අනුරාධපුර යුගයේ සීගිරි සිතුවම් 'දිව්‍ය ලෝකයේ හෝ රාජකීය සෞන්දර්යයේ' සංකේතයක් ලෙස හැඳින්වෙන්නේ ඇයි?", "කිසිදු බියක් හෝ දුකක් නොමැති සුන්දර ශාන්ත ප්‍රකාශනය නිසා", "යුද පිටියේ ජයග්‍රහණ පෙන්වන නිසා", "වෛද්‍ය ප්‍රතිකාර ක්‍රම පෙන්වන නිසා", "කෘෂිකාර්මික කටයුතු පෙන්වන නිසා", "සෑම රුවකම මුහුණේ ඇති ශාන්ත, මෘදු හා ප්‍රසන්න ස්වභාවය උසස් සෞන්දර්යයක් මවයි."),
        q("සීගිරි ලෙන් සිතුවම් පිටපත් කිරීමට හා සංරක්ෂණයට පුරෝගාමී වූ 'එල්. ටී. පී. මංජුශ්‍රී' මහතාගේ කාර්යභාරය කුමක්ද?", "සීගිරි ඇතුළු පෞරාණික බිතුසිතුවම් ඉතා නිවැරදිව පිටපත් කර ලේඛනගත කිරීම", "සීගිරි ගල මුදුනේ නව ගොඩනැගිලි තැනීම", "සීගිරි චිත්‍ර විදේශ රටවලට විකිණීම", "නව තෙල් සායම් සිතුවම් බිත්ති මත ඇඳීම", "මංජුශ්‍රී මහතා ලංකාවේ බිතුසිතුවම් උරුමය අනුරූ මගින් අනාගතයට සංරක්ෂණය කළේය."),
        q("සීගිරියේ 'බිතුසිතුවම් ලෙනට' පිවිසීමේදී පහළින් ඇති කැටපත් පවුරට ලැබුණු විශේෂ ලක්ෂණය කුමක්ද?", "විශේෂ බදාමයක් යොදා දර්පණයක් මෙන් ඔප දමා තිබීම", "වීදුරු කැබලි සම්පූර්ණයෙන් ඔබ්බවා තිබීම", "රන් තහඩුවලින් ආවරණය කර තිබීම", "මැටි පමණක් ගා රළුවට තැබීම", "හුණු, බිත්තර සුදුමද හා මීපැණි ආදිය මිශ්‍ර කර ඔප දැමූ පවුර කැටපත් පවුර නම් විය."),
        q("සීගිරි බිතුසිතුවම්වල භාවිත කළ 'කළු' වර්ණය නිපදවා ඇත්තේ කුමන ස්වභාවික ද්‍රව්‍යයකින්ද?", "දැව අඟුරු හෝ පහන් දැලි කුඩු", "තාර සහ කෘත්‍රිම තෙල්", "කළුගල් කුඩු පමණක්", "කළු ප්ලාස්ටික් උණු කර", "පොල් කටු අඟුරු හෝ ශාක අඟුරු ඉතා සියුම්ව අඹරා කළු වර්ණය ලබා ගෙන ඇත."),
        q("සීගිරි ලලනාවන්ගේ කෙස් කළඹවල ඇඳ ඇති සැරසිලි මගින් පෙනෙන්නේ කුමක්ද?", "මල්, පබළු සහ මුතු වැනි ආභරණවලින් සැරසූ උසස් කේශ විලාසිතා", "සරලව ගැට ගැසූ හිස් ආවරණ පමණක්", "හිස සම්පූර්ණයෙන් මුඩු කර තිබීම", "ලෝහ හිස්වැසුම් පැළඳ සිටීම", "විවිධ හැඩයෙන් යුත් කොණ්ඩා මෝස්තර හා මල් සැරසිලි සීගිරි චිත්‍රවල කැපී පෙනේ."),
        q("සීගිරි බිතුසිතුවම් හි රූපවල ඇති 'සෘජු හෝ වක්‍ර රේඛා සංයෝජනය' මගින් ඇති කරන හැඟීම කුමක්ද?", "සුන්දර ලාලිත්‍යය හා සංගීතමය රිද්මය", "කෝපාවිෂ්ට යුදමය ආතතිය", "යාන්ත්‍රික කාර්මික බව", "දැඩි ශීතල හා මරණීය බිය", "මෘදු වක්‍ර රේඛා මගින් කාන්තා සිරුරේ ලාලිත්‍යය හා රිද්මයානුකූල ගලායාම මතු කරයි."),
        q("සීගිරි බිතුසිතුවම්වල ඇතැම් ස්ථානවල 'අමතර බදාම ස්තර' හමු වීමෙන් පුරාවිද්‍යාඥයන් නිගමනය කරන්නේ කුමක්ද?", "සමහර චිත්‍ර පැරණි චිත්‍ර මත නැවත අලුත්වැඩියා කර ඇඳ ඇති බව", "බදාම කර්මාන්තශාලාවක් එහි තිබූ බව", "කාශ්‍යප රජු පසුකාලීනව චිත්‍ර මැකූ බව", "ගලේ ඉරිතැළීම් සිමෙන්තියෙන් වැසූ බව", "එක් යුගයක සිට තවත් කාලයක් ඇතුළත සිතුවම් අලුත් කර බදාම තට්ටු යොදා ඇති බව සොයාගෙන ඇත."),
        q("සීගිරි සිතුවම්වල කාන්තා මුහුණුවල 'නිකට හා කම්මුල්' පෙන්වා ඇති ආකාරය කෙබඳුද?", "පිරුණු වටකුරු බවකින් හා මෘදු සෙවණැල්ලකින්", "තියුණු හතරැස් හැඩයකින්", "රළු සීරුම් රේඛාවලින්", "කිසිදු සෙවණැල්ලක් නොමැතිව", "සම්භාව්‍ය සෞන්දර්යයට අනුව මෘදු වර්ණ සංක්‍රාන්තියෙන් මුහුණේ පිරුණු බව දක්වයි."),
        q("සීගිරි චිත්‍රවල පවතින 'පැතලි නොවන ආලෝක-අඳුරු බව' (Modeling) යනු කුමක්ද?", "රූපයේ පරිමාව හැඟවීමට වර්ණ ලා-තද කිරීම", "සියලු තැන්වල එකම වර්ණ ඝනකම තැබීම", "පසුබිම කළු රෙදිවලින් ආවරණය කිරීම", "රූපවලට වීදුරු ආවරණ දැමීම", "සිරුරේ උස් පහත් තැන් පෙන්වීමට වර්ණ ශ්‍රේණිගත කිරීම ආකෘතිකරණය නම් වේ."),
        q("සීගිරිය පර්වතයේ සිතුවම් ලෙන හැරුණු විට අනුරාධපුර යුගයේ 'වෙනත් කඳුකර නොවන' ගඩොල් නිර්මාණවල බිතුසිතුවම් තිබූ බවට සාක්ෂිය කුමක්ද?", "රුවන්වැලිසෑය හා මිහින්තලේ ධාතු ගර්භ සිතුවම්", "ගාලු කොටු බැම්මේ සිතුවම්", "මහනුවර ඇම්බැක්කේ දැව සිතුවම්", "කෝට්ටේ බලකොටු සිතුවම්", "දාගැබ්වල ධාතු ගර්භ අභ්‍යන්තරයේද අනුරාධපුර යුගයේ විශිෂ්ට බිතුසිතුවම් පැවති බව කැණීම්වලින් හෙළි විය."),
        q("සීගිරි සිතුවම්වල සිටින කාන්තාවන් අත දරා සිටින 'කඳුලු හෝ මල් වට්ටිය' වැනි අංග කුමක් සඳහා යොදා ගත්තාද?", "දේව පූජාවක් හෝ මල් ඉසීමේ සංකේතයක් ලෙස", "වෙළඳපොළේ මල් විකිණීම සඳහා", "වගා බිම්වලට පොහොර දැමීම සඳහා", "ආහාර පිසීමේ කුළුබඩු රැගෙන යාමට", "මල් තැටි ගෙන මල් පූජා කරන හෝ අහසින් මල් වස්සවන ආකාරය මෙයින් දැක්වේ."),
        q("සීගිරි සිතුවම් ඇඳ ඇති 'බටහිර මුහුණත' කලාත්මකව වාසිදායක වන්නේ කෙසේද?", "සවස් කාලයේ හිරු එළියෙන් ලෙන තුළ මෘදු ස්වභාවික ආලෝකයක් ලැබීම", "මුළු දවස පුරාම ඝන අඳුරේ පැවතීම", "මෝසම් සුළඟ කෙළින්ම සිතුවම් මත වැදීම", "සතුන්ට පහසුවෙන් ඇතුළු වීමට හැකි වීම", "සවස හිරු එළිය පර්වතයේ ආරක්ෂිත කුහරය මෘදුව ආලෝකවත් කරන බැවින් සිතුවම් මනාව දිස්වේ."),
        q("සීගිරි බිතුසිතුවම්වල දක්නට ලැබෙන 'රේඛාවේ නම්‍යශීලී බව' කුමන චිත්‍ර ශිල්පියෙකුගේ ලක්ෂණයක් පෙන්වයිද?", "මානව සිරුර හා සෞන්දර්යය ගැන මනා පළපුරුද්දක් ඇති දක්ෂ ශිල්පියෙකුගේ", "පළමු වරට පින්සලක් අතට ගත් ආධුනිකයෙකුගේ", "ජ්‍යාමිතික රූප පමණක් අඳින ඉංජිනේරුවෙකුගේ", "අකුරු පමණක් ලියන ලේඛකයෙකුගේ", "එක පින්සල් පහරින් පුළුල් වක්‍රතා නිවැරදිව ඇඳීම ශිල්පියාගේ විශිෂ්ට පරිචය පෙන්වයි."),
        q("සීගිරියේ පිහිටි සිතුවම් 'සාම්ප්‍රදායික බෞද්ධ විහාර සිතුවම්වලින්' වෙනස් වන ප්‍රධාන තේමාත්මක කරුණ කුමක්ද?", "රාජකීය හා ලෞකික සෞන්දර්ය රසය ප්‍රබලව ඉස්මතු වීම", "සියලු සිතුවම් යුද ජයග්‍රහණ දැක්වීම", "බුදු සිරිතේ ජාතක කතා පෙළට ඇඳ තිබීම", "යක්ෂ හා ප්‍රේත රූප බහුලව තිබීම", "ජාතක කතා වෙනුවට දිව්‍ය හා රාජකීය අප්සරාවන් තේමා කර ගැනීම සීගිරියේ සුවිශේෂීත්වයයි."),
        q("සීගිරි කලාගාරයේ 'පර්වත මතුපිට' බදාම ඇලවීම සඳහා මූලික පස් ස්තරය සකස් කළේ ඇයි?", "රළු ගල් මතුපිට සමතලා කර මතුපිට තට්ටුවට පදනම සැදීමට", "චිත්‍රයේ වර්ණ තද කළු පැහැ ගැන්වීමට", "පර්වතය කඩා දැමීම පහසු කිරීමට", "සිතුවම් පසුව ගලවා ගෙන යාමට", "නොසම ගල් පෘෂ්ඨය සමතලා කිරීමට හා තෙතමනය පාලනයට පළමු රළු මැටි ස්තරය යොදයි."),
        q("සීගිරි බිතුසිතුවම්වල ඇඳ ඇති සමහර කාන්තාවන්ගේ අත්ලෙහි හා ඇඟිලි තුඩුවල දැකිය හැකි විශේෂ වර්ණය කුමක්ද?", "ලා රතු හෝ මදටිය පැහැයෙන් වර්ණ ගන්වා තිබීම", "තද නිල් පැහැයෙන් වර්ණ ගන්වා තිබීම", "කළු අඟුරු පැහැයෙන් වැසී තිබීම", "කොළ පැහැයෙන් තිත් තබා තිබීම", "සෞන්දර්ය ලක්ෂණ අනුව ඇඟිලි තුඩු හා අත්ල රතු රත්තක්කා පැහැයෙන් අලංකාර කර තිබේ."),
        q("සීගිරි සිතුවම්වල පවතින 'ගතික ස්වභාවය' (Dynamic Movement) ප්‍රධාන වශයෙන් නිර්මාණය වී ඇත්තේ කුමකින්ද?", "කය නැමුණු ත්‍රිභංග ඉරියව්ව හා මල් ඉසින අත් චලනයෙන්", "රූප සියල්ල කෙළින් හිටගෙන සිටීමෙන්", "වේගයෙන් දුවන අශ්ව රථ ඇඳීමෙන්", "පසුබිමේ ගස් සුළඟට නැමී තිබීමෙන්", "උරහිස් හා ඉඟටියේ මෘදු නැමීම් මගින් රූපවලට සජීවී ගමන් ශෛලියක් ලැබී ඇත."),
        q("සීගිරි බිතුසිතුවම් අධ්‍යයනය කිරීමේදී 'මේඝලතා හා විජ්ජුලතා' අතර වර්ණ ප්‍රභේදයෙන් කලාකරුවා ලබා ගත් සෞන්දර්ය ප්‍රතිඵලය කුමක්ද?", "වර්ණ ප්‍රතිවිරෝධතාව (Contrast) මගින් දෙදෙනාම කැපී පෙනීම", "එක් රුවක් සම්පූර්ණයෙන් නොපෙනී යාම", "සිතුවම අවලස්සන හා අඳුරු වීම", "වර්ණ එකිනෙක මත දිය වී යාම", "රන්වන් හා අඳුරු පැහැ සංයෝජනය දෘශ්‍ය සමතුලිතතාව හා ප්‍රතිවිරෝධතාව ඉහළ නංවයි."),
        q("සීගිරිය පිළිබඳව ලෝකයේ විවිධ රටවල කලා විචාරකයන් දක්වන පොදු අදහස කුමක්ද?", "දකුණු ආසියාවේ පුරාණ ලෞකික බිතුසිතුවම් කලාවේ අග්‍රගණ්‍ය නිර්මාණයක් බව", "යුරෝපීය කලාවෙන් පසුව බිහි වූ අනුකරණයක් බව", "ප්‍රාග් ඓතිහාසික කුරුටු සටහන් පෙළක් බව", "කිසිදු ශිල්පීය වටිනාකමක් නැති සරල රූප බව", "අජන්තාවට සමගාමීව හෝ ඊටත් වඩා නිදහස් සෞන්දර්යයක් සීගිරි සිතුවම්වලින් පළ වේ."),
        q("සීගිරි බිතුසිතුවම් සංරක්ෂණය සඳහා නරඹන්නන්ට කැමරා ආලෝක ධාරා (Flash) භාවිතය තහනම් කර ඇත්තේ ඇයි?", "දැඩි ආලෝක තාපය හා විකිරණ නිසා ස්වභාවික ඛනිජ වර්ණ දුර්වර්ණ විය හැකි බැවින්", "කැමරාවලට චිත්‍ර පිටපත් නොවන බැවින්", "ගුහාව තුළ විදුලි කෙටීම් ඇති වන බැවින්", "පර්වතය කැඩී බිම වැටෙන බැවින්", "අධික ෆ්ලෑෂ් ආලෝකය සංවේදී පැරණි බදාම හා ඛනිජ වර්ණවල රසායනික ස්ථාවරත්වයට හානි කරයි."),
        q("සීගිරි කාන්තාවන්ගේ කන්වල පළඳවා ඇති 'තෝඩු හෙවත් කුණ්ඩලාභරණ' අධ්‍යයනයෙන් හඳුනාගන්නා ශිල්පීය හැකියාව කුමක්ද?", "සියුම් රන්කම් හා ලෝහ කැටයම් කලාවේ දියුණුව", "ප්ලාස්ටික් අච්චු කර්මාන්තයේ දියුණුව", "දැව කැටයම් කලාවේ දියුණුව", "මැටි පිළිස්සීමේ කර්මාන්තය", "විශාල රවුම් තෝඩු හා සියුම් මුතු ඇමිණුම් එකල රන්කරුවන්ගේ දක්ෂතාව ප්‍රකට කරයි."),
        q("සීගිරිය පර්වතයේ ඇති 'ලෙන් පොකුණ' හෙවත් චිත්‍ර ගුහාවේ පසුබිම් බිත්ති සකසා ඇත්තේ කුමන හැඩයකටද?", "පර්වතයේ වක්‍ර හැඩය අනුව යමින් සුමට කළ බදාම පෘෂ්ඨයක් ලෙස", "ඉතා තියුණු කෙළින් බිත්ති හතරක කාමරයක් ලෙස", "දැව ලෑලි ගසා සැදූ වේදිකාවක් ලෙස", "වීදුරු තහඩු සවි කළ කුටියක් ලෙස", "ස්වභාවික ගලේ වක්‍රතාවට අනුකූලව බදාම ආලේප කර සිතුවම් ඇඳ තිබීම මෙහි ලක්ෂණයකි."),
        q("සීගිරි සිතුවම්වල කාන්තාවන්ගේ මුහුණුවල 'දෘෂ්ටිය' (Gaze) යොමු වී ඇත්තේ කෙසේද?", "පහළට හෝ පැත්තට මෘදු කරුණාවන්ත බැල්මකින්", "කෙළින්ම නරඹන්නා දෙස රෞද්‍රව බලා සිටිමින්", "ඉහළ අහස දෙස කෝපයෙන් බලමින්", "දෑස් සම්පූර්ණයෙන් පියාගෙන සිටිමින්", "පහළට හෙළූ මෘදු බැල්ම රූපවල ශාන්තභාවය හා ගෞරවනීය බව තවත් වැඩි කරයි."),
        q("සීගිරි සිතුවම්කරණයේදී 'පින්සල භාවිතය' පිළිබඳ නිවැරදි විචාරාත්මක නිරීක්ෂණය කුමක්ද?", "සිහින් රේඛා සඳහා සියුම් පින්සල් හා වර්ණ පිරවීමට පළල් පින්සල් භාවිතය", "සියල්ල අතේ ඇඟිලිවලින් පමණක් ඇඳීම", "විශාල කොසු මගින් පමණක් තීන්ත ගෑම", "පිහි තලයකින් පමණක් වර්ණ ඇතිරීම", "රේඛා පාලනය හා මෘදු සෙවණැලි සඳහා විවිධ ප්‍රමාණයේ සියුම් සත්ව ලොම් පින්සල් භාවිත කර ඇත."),
        q("සීගිරි බිතුසිතුවම්වල 'සමමිතිය' (Symmetry) පවත්වා ඇති ආකාරය කුමක්ද?", "සෘජු කණ්ණාඩි සමමිතිය වෙනුවට අසමමිතික රිද්මයානුකූල සමතුලිතතාවක්", "සියලු රූප වමේ හා දකුණේ එකම අයුරින් පිටපත් කිරීම", "කිසිදු සමතුලිතතාවක් නොමැතිව විසිරවීම", "හරි මැදින් සිරස් ඉරක් ගසා දෙපස සමාන කිරීම", "යුගල රූපවල පවා එකිනෙකට වෙනස් හස්ත ඉරියව් යොදා ස්වභාවික සමතුලිතතාවක් මවා ඇත."),
        q("සීගිරි කුරුටු ගී කියැවීමෙන් සිතුවම්වල 'කාලයත් සමඟ සිදු වූ වෙනසක්' හඳුනා ගන්නේ කෙසේද?", "වර්තමානයේ ඉතිරිව ඇති රූප 22ට වඩා විශාල ප්‍රමාණයක් මුලදී තිබූ බව දැනගැනීමෙන්", "සිතුවම් පසුව මහනුවර යුගයේදී ඇඳි බව හෙළි වීමෙන්", "චිත්‍රවල පිරිමි රූප දහසක් තිබූ බව දැනගැනීමෙන්", "සියලු චිත්‍ර නිල් පැහැයෙන් තිබූ බව හෙළි වීමෙන්", "පන්සියයක් ලලනාවන් ගැන කවිවල සඳහන් වීමෙන් පැරණි විශාලත්වය තහවුරු වේ."),
        q("සීගිරි සිතුවම් අධ්‍යයනය කිරීම O/L චිත්‍ර කලා සිසුවෙකුට ප්‍රායෝගිකව වැදගත් වන්නේ කෙසේද?", "රේඛා පාලනය, වර්ණ සංකලනය සහ සිරුරේ පරිමාව මතු කිරීම ඉගෙන ගැනීමට", "තෙල් සායම් නළ මිලදී ගන්නා ආකාරය ඉගෙනීමට", "කැන්වස් රෙදි මැසීම ඉගෙන ගැනීමට", "ඩිජිටල් ත්‍රිමාණ මෘදුකාංග ක්‍රියාත්මක කිරීමට", "දේශීය වර්ණ භාවිතය හා රිද්මයානුකූල මානව රූප ඇඳීම ප්‍රගුණ කිරීමට මෙය විශිෂ්ට ආදර්ශයකි.")
    )
}
